import urllib.request, sys

url = 'https://raw.githubusercontent.com/dwyl/english-words/master/words_alpha.txt'
print('Downloading...')
data = urllib.request.urlopen(url).read().decode('utf-8').splitlines()
print('Lines:', len(data))

# Build prefix set and word set (only alphabetic words)
word_set = set()
prefix_set = set()
for w in data:
    w = w.strip().lower()
    if not w.isalpha():
        continue
    word_set.add(w)
    # only need prefixes up to length 16 (board max)
    maxlen = min(len(w), 16)
    for i in range(1, maxlen+1):
        prefix_set.add(w[:i])

print('Dictionary loaded. Words:', len(word_set), 'Prefixes:', len(prefix_set))

grid = [list("abrl"), list("eite"), list("ions"), list("fpei")]
rows, cols = 4, 4

neighbors = {}
for r in range(rows):
    for c in range(cols):
        nbrs = []
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==0 and dc==0: continue
                nr, nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols:
                    nbrs.append((nr,nc))
        neighbors[(r,c)] = nbrs

visited = [[False]*cols for _ in range(rows)]
results = set()

def dfs(r, c, path):
    path += grid[r][c]
    if path not in prefix_set:
        return
    if path in word_set and len(path) >= 3:
        results.add(path)
    if len(path) == 16:
        return
    visited[r][c] = True
    for nr, nc in neighbors[(r,c)]:
        if not visited[nr][nc]:
            dfs(nr, nc, path)
    visited[r][c] = False

for r in range(rows):
    for c in range(cols):
        dfs(r, c, "")

print('Total valid words found:', len(results))
if results:
    max_len = max(len(w) for w in results)
    longest = sorted([w for w in results if len(w)==max_len])
    print('Max length:', max_len)
    print('Longest words (alphabetical first few):', longest[:10])
    print('Answer:', longest[0])
